#include <cstdio>
#include <vector>
#include <string>
#include <iostream>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<std::string> w(n);
    std::getline(std::cin, w[0]);
    for (int i = 0; i < n; ++i) std::getline(std::cin, w[i]);

    int k = (int)w[0].size();
    for (int i = 1; i < n && k > 0; ++i) {
        int j = 0;
        while (j < k && j < (int)w[i].size() && w[i][j] == w[0][j]) ++j;
        k = j;
    }
    printf("%s\n", w[0].substr(0, k).c_str());
    return 0;
}
